from ._ute_legacy.ute_testline_configuration.ute_config import Config


class EditableConfig(Config):

    """
    This class provides UTE configuration and sets attributes to it from parameters of the function __setattr__.

    :param name: project name
    :param value: values of the project like ip address

    Exception:
    If section name is different than the "_attributes", there is assigned value to _attributes[name] section.
    """

    def __setattr__(self, name, value):

        super(Config, self).__setattr__(name, value)
        if name != '_attributes':
            self._attributes[name] = value
